$content = [System.Text.Encoding]::UTF8.GetString([System.IO.File]::ReadAllBytes($path))

# Anchor: the entire transformer block L136-L181
$oldBlock = '    const projectsAsLaunches = (Array.isArray(liveProjects) ? liveProjects : [])' + "`n" + '      .filter(p => p && (p.launchDate || p.projectStartDate || p.status === "Off-Plan"))' + "`n" + '      .map(p => ({' + "`n" + '        id: p.id || ("live-" + Math.random().toString(36).slice(2)),' + "`n" + '        project: p.project || p.name || "Unnamed",' + "`n" + '        developer: p.developer || p.developerName || "Unknown",' + "`n" + '        community: p.community || p.district || "Dubai",' + "`n" + '        type: p.type || "Apartment",' + "`n" + '        tier: p.tier || 2,' + "`n" + '        branded: !!p.branded,' + "`n" + '        launchDate: p.launchDate || p.projectStartDate || "",' + "`n" + '        eoiDeadline: p.eoiDeadline || "",' + "`n" + '        status: p.status || "Off-Plan",' + "`n" + '        units: p.totalUnits || p.units || 0,' + "`n" + '        soldUnits: p.unitsSold || 0,' + "`n" + '        startingPrice: p.priceMin || 0,' + "`n" + '        pricePerSqft: p.ppsf || 0,' + "`n" + '        avgUnitSize: p.avgUnitSize || 0,' + "`n" + '        eoiAmount: p.eoiAmount || 0,' + "`n" + '        eoiRefundable: !!p.eoiRefundable,' + "`n" + '        paymentPlan: p.paymentPlan || { dp: 10, construction: 70, handover: 20, postHandover: 0, label: p.payment || "10/70/20" },' + "`n" + '        handover: p.handoverQuarter || p.handover || p.expectedHandover || "",' + "`n" + '        developerOnTimeRate: p.devOnTimeRate || (p.tier === 1 ? 85 : 70),' + "`n" + '        communityAvgPpsf: p.communityAvgPpsf || p.ppsf || 0,' + "`n" + '        appreciationToHandover: p.appreciationToHandover || 0,' + "`n" + '        goldenVisa: !!p.goldenVisa,' + "`n" + '        metroDistanceKm: p.distMetro || 0,' + "`n" + '        beachAccess: !!p.beachAccess,' + "`n" + '        insight: p.overview || p.description || p.insight || "",' + "`n" + '        velocityScore: p.velocityScore || 0,' + "`n" + '        tags: Array.isArray(p.tags) ? p.tags : [],' + "`n" + '        grossYield: p.grossYield || 0,' + "`n" + '        netYield: p.netYield || 0,' + "`n" + '        serviceCharge: p.serviceCharge || 0,' + "`n" + '        commission: p.commission || 2,' + "`n" + '        investmentScore: p.investmentScore || 0,' + "`n" + '        developerScore: p.developerScore || (p.tier === 1 ? 85 : 70),' + "`n" + '        reraNo: p.reraNo || p.dldNumber || p.projectNumber || "",' + "`n" + '        escrowBank: p.escrowBank || "",' + "`n" + '        plotMin: p.plotSize || 0, plotMax: p.plotSize || 0,' + "`n" + '        distances: { metro: p.distMetro || 0, difc: p.distDIFC || 0, airport: p.distAirport || 0, beach: p.distBeach || 0, mall: p.distMall || 0, school: p.distSchool || 0, hospital: p.distHospital || 0 },' + "`n" + '        amenities: Array.isArray(p.amenities) ? p.amenities : [],' + "`n" + '        views: Array.isArray(p.view) ? p.view : (Array.isArray(p.views) ? p.views : []),' + "`n" + '        unitBreakdown: Array.isArray(p.unitBreakdown) ? p.unitBreakdown : [],' + "`n" + '        isLive: true,' + "`n" + '      }));'

