Write-Host "Anchor matches: $c"
if ($c -ne 1) { Write-Host "Anchor not unique - aborting" -ForegroundColor Red; exit 1 }

$newBlock = '    // PROFESSIONAL TRANSFORMER - reads real Firestore fields, zero fabricated defaults' + "`n" + '    // Developer on-time research-backed lookup (inline - mirror of HandoverTab DEVELOPER_INDEX)' + "`n" + '    const LC_DEV_ONTIME = {' + "`n" + '      "sobha realty": 91, "emaar": 88, "ellington properties": 88, "majid al futtaim": 87,' + "`n" + '      "omniyat": 85, "mira developments": 82, "nakheel": 80, "london gate": 78,' + "`n" + '      "dubai investments real estate": 75, "binghatti": 74, "damac properties": 71,' + "`n" + '      "object 1 development": 70, "bigfoot developers": 68,' + "`n" + '    };' + "`n" + '    const lookupDevOnTime = (devName) => {' + "`n" + '      if (!devName) return null;' + "`n" + '      const needle = String(devName).toLowerCase().trim();' + "`n" + '      for (const k of Object.keys(LC_DEV_ONTIME)) {' + "`n" + '        if (k === needle || needle.includes(k) || k.includes(needle)) return LC_DEV_ONTIME[k];' + "`n" + '      }' + "`n" + '      return null; // honest: unknown = null, not fake 85' + "`n" + '    };' + "`n" + '' + "`n" + '    const projectsAsLaunches = (Array.isArray(liveProjects) ? liveProjects : [])' + "`n" + '      .filter(p => p && (p.launchDate || p.projectStartDate || p.status === "Off-Plan"))' + "`n" + '      .map(p => {' + "`n" + '        // Compute appreciation honestly' + "`n" + '        let appreciation = null;' + "`n" + '        if (typeof p.appreciationToHandover === "number") appreciation = p.appreciationToHandover;' + "`n" + '        else if (p.priceMinAtLaunch && p.priceMin) {' + "`n" + '          appreciation = Math.round(((p.priceMin - p.priceMinAtLaunch) / p.priceMinAtLaunch) * 100 * 10) / 10;' + "`n" + '        }' + "`n" + '' + "`n" + '        // Parse payment plan - may be object, may be string like "90/10"' + "`n" + '        let paymentPlanObj;' + "`n" + '        if (p.paymentPlan && typeof p.paymentPlan === "object") {' + "`n" + '          paymentPlanObj = p.paymentPlan;' + "`n" + '        } else {' + "`n" + '          const planStr = (typeof p.paymentPlan === "string" ? p.paymentPlan : "") || p.payment || "";' + "`n" + '          const parts = planStr.split("/").map(n => parseInt(n, 10)).filter(n => !isNaN(n));' + "`n" + '          paymentPlanObj = parts.length >= 2' + "`n" + '            ? { dp: parts[0], construction: 0, handover: parts[1], postHandover: parts[2] || 0, label: planStr }' + "`n" + '            : { dp: null, construction: null, handover: null, postHandover: null, label: planStr || "TBD" };' + "`n" + '        }' + "`n" + '' + "`n" + '        return {' + "`n" + '          id: p.id || ("live-" + Math.random().toString(36).slice(2)),' + "`n" + '          project: p.project || p.name || "Unnamed",' + "`n" + '          developer: p.developer || p.developerName || "Unknown",' + "`n" + '          community: p.community || p.area || "Dubai",' + "`n" + '          type: p.type || p.propertyType || "Apartment",' + "`n" + '          tier: p.tier || null,' + "`n" + '          branded: !!p.branded,' + "`n" + '          launchDate: p.launchDate || p.projectStartDate || "",' + "`n" + '          eoiDeadline: p.eoiDeadline || "",' + "`n" + '          status: p.status || "Off-Plan",' + "`n" + '          units: p.totalUnits || p.residentialUnits || p.units || null,' + "`n" + '          soldUnits: p.unitsSold || null,' + "`n" + '          startingPrice: p.priceMin || null,' + "`n" + '          pricePerSqft: p.ppsf || null,' + "`n" + '          avgUnitSize: p.unitSizeAvgSqFt || p.avgUnitSize || null,' + "`n" + '          sizeMin: p.unitSizeMinSqFt || p.sizeMin || null,' + "`n" + '          sizeMax: p.unitSizeMaxSqFt || p.sizeMax || null,' + "`n" + '          eoiAmount: p.eoiAmount || null,' + "`n" + '          eoiRefundable: !!p.eoiRefundable,' + "`n" + '          paymentPlan: paymentPlanObj,' + "`n" + '          handover: p.handover || p.expectedHandover || p.handoverQuarter || p.handoverMonth || "",' + "`n" + '          developerOnTimeRate: lookupDevOnTime(p.developer || p.developerName),' + "`n" + '          communityAvgPpsf: p.communityAvgPpsf || null,' + "`n" + '          appreciationToHandover: appreciation,' + "`n" + '          goldenVisa: !!p.goldenVisa,' + "`n" + '          metroDistanceKm: typeof p.distMetro === "number" ? p.distMetro : null,' + "`n" + '          beachAccess: typeof p.distBeach === "number" ? p.distBeach < 1 : !!p.beachAccess,' + "`n" + '          insight: p.description || p.overview || p.insight || "",' + "`n" + '          velocityScore: p.velocityScore || null,' + "`n" + '          tags: Array.isArray(p.tags) ? p.tags : [],' + "`n" + '          grossYield: typeof p.grossYield === "number" ? p.grossYield : null,' + "`n" + '          netYield: typeof p.netYield === "number" ? p.netYield : null,' + "`n" + '          serviceCharge: typeof p.serviceCharge === "number" ? p.serviceCharge : null,' + "`n" + '          commission: typeof p.commission === "number" ? p.commission : null,' + "`n" + '          investmentScore: p.investmentScore || null,' + "`n" + '          developerScore: lookupDevOnTime(p.developer || p.developerName), // same as on-time rate, honest' + "`n" + '          reraNo: p.reraNo || p.dldProjectNumber || p.projectNumber || "",' + "`n" + '          escrowBank: p.escrowBank || "",' + "`n" + '          plotMin: p.plotSize || null, plotMax: p.plotSize || null,' + "`n" + '          distances: {' + "`n" + '            metro: typeof p.distMetro === "number" ? p.distMetro : null,' + "`n" + '            difc: typeof p.distDIFC === "number" ? p.distDIFC : null,' + "`n" + '            airport: typeof p.distAirport === "number" ? p.distAirport : null,' + "`n" + '            beach: typeof p.distBeach === "number" ? p.distBeach : null,' + "`n" + '            mall: typeof p.distMall === "number" ? p.distMall : null,' + "`n" + '            school: typeof p.distSchool === "number" ? p.distSchool : null,' + "`n" + '            hospital: typeof p.distHospital === "number" ? p.distHospital : null,' + "`n" + '          },' + "`n" + '          amenities: Array.isArray(p.amenities) ? p.amenities : [],' + "`n" + '          views: Array.isArray(p.view) ? p.view : (Array.isArray(p.views) ? p.views : []),' + "`n" + '          unitBreakdown: Array.isArray(p.unitBreakdown) ? p.unitBreakdown : [],' + "`n" + '          isLive: true,' + "`n" + '          _dataQuality: p.dataQualityScore || null,' + "`n" + '        };' + "`n" + '      });'

$content = $content.Replace($oldBlock, $newBlock)

$hasLookup = $content.Contains('lookupDevOnTime')
$hasLcDev = $content.Contains('LC_DEV_ONTIME')
$hasAppreciationCompute = $content.Contains('priceMinAtLaunch && p.priceMin')
$hasOldFake85 = $content.Contains('developerOnTimeRate: p.devOnTimeRate || (p.tier === 1 ? 85 : 70)')
$hasOldFake2 = $content.Contains('developerScore: p.developerScore || (p.tier === 1 ? 85 : 70)')

Write-Host ""
Write-Host "Verification:"
Write-Host "  lookupDevOnTime helper added: $hasLookup"
Write-Host "  LC_DEV_ONTIME map added: $hasLcDev"
Write-Host "  Appreciation compute logic: $hasAppreciationCompute"
Write-Host "  Old fake 85 removed (on-time): $(-not $hasOldFake85)"
Write-Host "  Old fake 85 removed (devScore): $(-not $hasOldFake2)"

if (-not ($hasLookup -and $hasLcDev -and $hasAppreciationCompute) -or $hasOldFake85 -or $hasOldFake2) {
  Write-Host "Verification FAILED - reverting" -ForegroundColor Red
  Copy-Item $backup $path -Force
  exit 1
}

[System.IO.File]::WriteAllBytes($path, [System.Text.Encoding]::UTF8.GetBytes($content))
Write-Host ""
Write-Host "LAUNCH CALENDAR TRANSFORMER PROFESSIONALLY REWRITTEN" -ForegroundColor Green